typedef struct visitor_ops {
    size_t size;                                          /* capability marker */
    void (*visit_default)(visitor *, const element *);
    void (*visit_union)(visitor *, const union_shape *);  /* added with the new element */
} visitor_ops;

static void union_shape_accept(const union_shape *u, visitor *v) {
    if (v->ops->size > 2) v->ops->visit_union(v, u);      /* probe: does it know me? */
    else                  v->ops->visit_default(v, (const element *)u);  /* predates me */
}
